export interface JaSeoArticle {
  slug: string;
  title: string;
  description: string;
  href: string;
  date: string;
  category: string;
  image: string;
  tags: string[];
  intro: string[];
  toc: { id: string; label: string }[];
  sections: {
    id: string;
    title: string;
    paragraphs: string[];
    highlight?: {
      label: string;
      text: string;
    };
    items?: string[];
  }[];
  ctaTitle: string;
}

const article = (
  data: Omit<JaSeoArticle, 'href' | 'category'> & { category?: string },
): JaSeoArticle => {
  const { category = 'ホットクック', ...rest } = data;

  return {
    ...rest,
    href: `/blog/${data.slug}/`,
    category,
  };
};

